ALTER TABLE dyn2_campi MODIFY descrizione VARCHAR2(4000);

CREATE OR REPLACE VIEW VW_GEO_PRATICHECATASTO AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE, ISTANZE.SOFTWARE AS MODULO, ISTANZE.CODICEISTANZA AS IDPRATICA, ISTANZE.NUMEROISTANZA AS NUMEROPRATICA, ISTANZE.DATA AS DATAPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA, VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA, STATIISTANZA.STATO AS STATOPRATICA, CATASTO.DESCRIZIONE AS TIPOCATASTO, ISTANZEMAPPALI.SEZIONE AS SEZIONE, ISTANZEMAPPALI.FOGLIO, ISTANZEMAPPALI.PARTICELLA, ISTANZEMAPPALI.SUB, ISTANZEMAPPALI.FKIDISTANZESTRADARIO AS IDINDIRIZZO FROM ISTANZE INNER JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA INNER JOIN ISTANZEMAPPALI ON ISTANZEMAPPALI.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZEMAPPALI.FKCODICEISTANZA = ISTANZE.CODICEISTANZA LEFT OUTER JOIN CATASTO ON CATASTO.CODICE = ISTANZEMAPPALI.CODICECATASTO; 
CREATE OR REPLACE VIEW VW_GEO_PRATICHEINDIRIZZI AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE, ISTANZE.SOFTWARE AS MODULO, ISTANZE.CODICEISTANZA AS IDPRATICA, ISTANZE.NUMEROISTANZA AS NUMEROPRATICA, ISTANZE.DATA AS DATAPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA, VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA, STATIISTANZA.STATO AS STATOPRATICA, ISTANZESTRADARIO.ID AS IDINDIRIZZO, STRADARIO.CODVIARIO, STRADARIO.PREFISSO AS TOPONIMO, STRADARIO.DESCRIZIONE AS DESCVIA, ISTANZESTRADARIO.CODICECIVICO, ISTANZESTRADARIO.CIVICO, ISTANZESTRADARIO.COLORE, ISTANZESTRADARIO.FRAZIONE, ISTANZESTRADARIO.CIRCOSCRIZIONE, ISTANZESTRADARIO.CAP, ISTANZESTRADARIO.KM, ISTANZESTRADARIO.ESPONENTE, ISTANZESTRADARIO.SCALA, ISTANZESTRADARIO.INTERNO, ISTANZESTRADARIO.ESPONENTEINTERNO, ISTANZESTRADARIO.FABBRICATO, ISTANZESTRADARIO.PIANO, ISTANZESTRADARIO.QUARTIERE, ISTANZESTRADARIO.ID_PUNTO_SIT, ISTANZESTRADARIO.UUID, ISTANZESTRADARIO.LATITUDINE, ISTANZESTRADARIO.LONGITUDINE FROM ISTANZE, VW_ALBEROPROC, STATIISTANZA, ISTANZESTRADARIO, STRADARIO WHERE VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC AND STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA AND ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA AND STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO; 
CREATE OR REPLACE VIEW VW_GEO_ATTIVITAINDIRIZZI AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE AS MODULO, I_ATTIVITA.ID AS IDATTIVITA, I_ATTIVITA.DENOMINAZIONE AS DENOMINAZIONE_ATTIVITA, ANAGRAFE.NOMINATIVO AS RAGIONESOCIALE, I_ATTIVITA.ATTIVA AS ATTIVA, I_ATTIVITA.OPERANTE AS OPERANTE, ISTANZE.CODICEISTANZA AS IDPRATICA, ISTANZE.NUMEROISTANZA AS NUMEROPRATICA, ISTANZE.DATA AS DATAPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA, VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA, STATIISTANZA.STATO AS STATOPRATICA, ISTANZESTRADARIO.ID AS IDINDIRIZZO, STRADARIO.CODVIARIO, STRADARIO.PREFISSO AS TOPONIMO, STRADARIO.DESCRIZIONE AS DESCVIA, ISTANZESTRADARIO.CODICECIVICO, ISTANZESTRADARIO.CIVICO, ISTANZESTRADARIO.COLORE, ISTANZESTRADARIO.FRAZIONE, ISTANZESTRADARIO.CIRCOSCRIZIONE, ISTANZESTRADARIO.CAP, ISTANZESTRADARIO.KM, ISTANZESTRADARIO.ESPONENTE, ISTANZESTRADARIO.SCALA, ISTANZESTRADARIO.INTERNO, ISTANZESTRADARIO.ESPONENTEINTERNO, ISTANZESTRADARIO.FABBRICATO, ISTANZESTRADARIO.PIANO, ISTANZESTRADARIO.QUARTIERE, ISTANZESTRADARIO.ID_PUNTO_SIT, ISTANZESTRADARIO.UUID, ISTANZESTRADARIO.LATITUDINE, ISTANZESTRADARIO.LONGITUDINE FROM ISTANZE LEFT OUTER JOIN ANAGRAFE ON ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE INNER JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA INNER JOIN ISTANZESTRADARIO ON ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA INNER JOIN STRADARIO ON STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO INNER JOIN I_ATTIVITA ON ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
CREATE OR REPLACE VIEW VW_GEO_ATTIVITACATASTO AS SELECT ISTANZE.IDCOMUNE AS INSTALLAZIONE, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE AS MODULO, I_ATTIVITA.ID AS IDATTIVITA, I_ATTIVITA.DENOMINAZIONE AS DENOMINAZIONE_ATTIVITA, ANAGRAFE.NOMINATIVO AS RAGIONESOCIALE, I_ATTIVITA.ATTIVA AS ATTIVA, I_ATTIVITA.OPERANTE AS OPERANTE, ISTANZE.CODICEISTANZA AS IDPRATICA, ISTANZE.NUMEROISTANZA AS NUMEROPRATICA, ISTANZE.DATA AS DATAPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEPADRE AS DESCSEZIONEPRATICA, VW_ALBEROPROC.SC_CODICE AS CODTIPOPRATICA, VW_ALBEROPROC.SC_DESCRIZIONEBREVE AS DESCTIPOPRATICA, STATIISTANZA.STATO AS STATOPRATICA, CATASTO.DESCRIZIONE AS TIPOCATASTO, ISTANZEMAPPALI.SEZIONE AS SEZIONE, ISTANZEMAPPALI.FOGLIO, ISTANZEMAPPALI.PARTICELLA, ISTANZEMAPPALI.SUB, ISTANZEMAPPALI.FKIDISTANZESTRADARIO AS IDINDIRIZZO FROM I_ATTIVITA INNER JOIN ISTANZE ON ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA LEFT OUTER JOIN ANAGRAFE ON ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE INNER JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC INNER JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA INNER JOIN ISTANZEMAPPALI ON ISTANZEMAPPALI.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZEMAPPALI.FKCODICEISTANZA = ISTANZE.CODICEISTANZA LEFT OUTER JOIN CATASTO ON CATASTO.CODICE = ISTANZEMAPPALI.CODICECATASTO;

ALTER TABLE istanzestradario MODIFY codicecivico VARCHAR2(50);
ALTER TABLE PEC_INBOX  MODIFY PEC_DATE TIMESTAMP;

ALTER TABLE I_ATTIVITA_SNAPSHOT MODIFY (DATA DATE NOT NULL);


CREATE TABLE ISTANZEDELETE (
CODICEISTANZA NUMBER(6,0) NOT NULL, 
IDCOMUNE VARCHAR2(6 BYTE) NOT NULL, 
SOFTWARE VARCHAR2(2 BYTE) NOT NULL, 
DATACANCELLAZIONE DATE,
DATANOTIFICA DATE,
IDNOTIFICA VARCHAR2(50 BYTE),
CAMPI_ISTANZA CLOB,
ID NUMBER(10,0) NOT NULL,
CONSTRAINT ISTANZEDELETE_PK PRIMARY KEY (ID)
);

CREATE TABLE ISTANZEDOSSIER (
CODICEISTANZA NUMBER(6,0) NOT NULL, 
IDCOMUNE VARCHAR2(6 BYTE) NOT NULL, 
SOFTWARE VARCHAR2(2 BYTE) NOT NULL, 
IDFLUSSO VARCHAR2(50 BYTE),
DATAINVIO DATE,      
IDRISPOSTA VARCHAR2(20 BYTE)
);

CREATE INDEX ISTANZEDOSSIER_INDEX1 ON ISTANZEDOSSIER (IDCOMUNE, CODICEISTANZA);